window.FIXTURES=window.FIXTURES||{};window.FIXTURES["speech"]={"vid":"HlV7Zp4iOLk","speaker":"Surangel Whipps","role":"President","country":"Palau","region":"Asia-Pacific","url":"https://www.youtube.com/watch?v=HlV7Zp4iOLk","date":"20260923","title":"🇵🇼 Palau - President Addresses United Nations General Debate, 81st Session | #UNGA","seconds":995,"words":1668,"counts":{"claims":23,"promises":0,"attacks":0},"topics":[{"topic":"Climate change","share":0.1508,"seconds":150},{"topic":"Climate finance","share":0.1343,"seconds":134},{"topic":"Pacific ocean","share":0.0856,"seconds":85},{"topic":"Nicotine addiction","share":0.0683,"seconds":68},{"topic":"Palau energy","share":0.0666,"seconds":66},{"topic":"Taiwan UN participation","share":0.0653,"seconds":65},{"topic":"Pacific security","share":0.0646,"seconds":64},{"topic":"Iran","share":0.0641,"seconds":64},{"topic":"Palau ocean policy","share":0.0635,"seconds":63},{"topic":"Russia Ukraine war","share":0.0632,"seconds":63},{"topic":"UNGA greetings","share":0.0631,"seconds":63},{"topic":"Pacific energy","share":0.0618,"seconds":61},{"topic":"Multilateralism","share":0.0489,"seconds":49}],"timeline":[[2,65,"UNGA greetings"],[67,150,"Climate change"],[151,236,"Pacific ocean"],[238,301,"Palau ocean policy"],[302,373,"Climate finance"],[375,437,"Climate finance"],[439,506,"Nicotine addiction"],[508,569,"Pacific energy"],[571,637,"Palau energy"],[639,702,"Russia Ukraine war"],[703,766,"Iran"],[768,832,"Pacific security"],[833,898,"Taiwan UN participation"],[899,966,"Climate change"],[968,1017,"Multilateralism"]],"stances":{"UNGA greetings":"Surangel Whipps extends warm greetings to the assembly and thanks Secretary-General Antonio Guterres for his leadership.","Climate change":"Surangel Whipps emphasizes that climate leadership and multilateralism are vital for small island developing states, whose sovereignty depends on a healthy ocean and stable climate.","Pacific ocean":"Surangel Whipps states that small island states and Pacific leaders have raised climate ambition, demonstrated ocean stewardship, and launched the Unlocking Blue Pacific Prosperity initiative to mobilize investment for sustainable ocean management.","Palau ocean policy":"Surangel Whipps states that Palau is implementing a sustainable ocean policy and developing infrastructure with partner support to ensure resource value and community resilience.","Climate finance":"Surangel Whipps calls for accessible, grant-based financing and full support for loss and damage to address climate change without adding debt to vulnerable nations.","Nicotine addiction":"Surangel Whipps advocates for global policies to reduce nicotine appeal and affordability, citing the need to protect children from an industry built on addiction.","Pacific energy":"Surangel Whipps advocates for a transition to 100% renewable energy in the Pacific to reduce vulnerability to external shocks and uncontrolled fuel prices.","Palau energy":"Surangel Whipps states that Palau is implementing national actions to reduce fossil fuel use through renewable energy and policies that ensure affordability and reliability, while emphasizing that international partnerships must respect the nation's sovereignty and values.","Russia Ukraine war":"Surangel Whipps states that the Russia-Ukraine war serves as a painful reminder of the human toll when diplomacy fails and violence erupts.","Iran":"Surangel Whipps upholds the sovereignty of several Middle Eastern nations and condemns Iran's actions that jeopardize maritime security.","Pacific security":"Surangel Whipps advocates for resolving tensions through dialogue and inclusion while rejecting the Pacific as a theater for geopolitical competition.","Taiwan UN participation":"Surangel Whipps argues that the UN marginalizes Taiwan's 23 million people and calls for a reversal of misrepresentations of rules to allow their meaningful participation.","Multilateralism":"Surangel Whipps advocates for a multilateral approach that respects diverse forms of knowledge and voices to achieve global peace."},"claims":[{"t":32,"quote":"Mr. President, congratulations on your election as President of the 81st session of the UN General Assembly.","topic":"UNGA greetings","kind":"fact"},{"t":129,"quote":"UNEP's latest findings make clear that the world is now certain to exceed","topic":"Climate change","kind":"fact"},{"t":194,"quote":"Pacific leaders have charted a practical roadmap through the unlocking blue Pacific prosperity UBPPP launched at COP 28 and reinforced by the Pacific leaders ocean statement adopted in Palao.","topic":"Pacific ocean","kind":"fact"},{"t":211,"quote":"UBBB unites 22 Pacific countries and territories to mobilize accessible catalytic catalytic investment for 100% sustainable ocean management robust food systems and resilience advancing our shared 30 by30 commitment.","topic":"Pacific ocean","kind":"number"},{"t":254,"quote":"We have launched our sustainable ocean policy that commits 100% effective science-based and adaptive management of our ocean","topic":"Palau ocean policy","kind":"fact"},{"t":282,"quote":"we are working to develop fishing ports and other critical infrastructure to truly capture the value of resources harvested in our waters","topic":"Palau ocean policy","kind":"fact"},{"t":323,"quote":"countries already bearing the cost of the problems they did not create","topic":"Climate finance","kind":"fact"},{"t":356,"quote":"Those who contributed the least to this climate crisis yet confront the worst threats of rising sea levels","topic":"Climate finance","kind":"fact"},{"t":395,"quote":"The Antigua and Barbuda agenda for SIDS provides a strong roadmap for resilience, but requires urgent, predictable, and scaled up support.","topic":"Climate finance","kind":"fact"},{"t":414,"quote":"The PRF is the first Pacific leown owned and managed regional financing facility dedicated to climate and disaster resilience and the first international institution collectively owned by the Pacific focused on turning resources into real community level resilience.","topic":"Climate finance","kind":"self_credit"},{"t":461,"quote":"Her efforts led to the formal request to the UN tech secretary general to initiate a WHO review of nicotine as a psychotropic substance.","topic":"Nicotine addiction","kind":"fact"},{"t":474,"quote":"Globally, nicotine claims over se seven million lives annually and more than a billion trap in addiction.","topic":"Nicotine addiction","kind":"number"},{"t":536,"quote":"Through the call to action, the Pacific reaffirmed a shared vision of 100% renewable energy and a just, inclusive and equitable transition away from fossil fuels.","topic":"Pacific energy","kind":"fact"},{"t":575,"quote":"Our latest commitment targets a 44% reduction in fossil fuel use by supported by renewable energy generation and practical policies that make the transition affordable and reliable.","topic":"Palau energy","kind":"number"},{"t":667,"quote":"The Russia Ukraine war is a painful reminder of the tragic human toll that occurs when diplomacy gives way to conflict and how challenging it is to deescalate tensions once violence erupts.","topic":"Russia Ukraine war","kind":"fact"},{"t":682,"quote":"The straight of Hormuz situation demonstrates how quickly disruption in an important waterway threatens international stability, energy security and trade worldwide.","topic":"Russia Ukraine war","kind":"fact"},{"t":703,"quote":"We uphold the sovereignty of Ba Bahrain, Jordan, Kuwait, Oman, Qatar, Saudi Arabia, and the UAE and condemn the actions of that of Iran to jeopardize maritime security and aim to obstruct, close and inter interfere with international navigation through the strait.","topic":"Iran","kind":"fact"},{"t":726,"quote":"At our Pacific leaders meeting in Palao, leaders expressed deep concern that China's ballistic missile test overflow several Pacific nations without adequate nos notice.","topic":"Iran","kind":"fact"},{"t":808,"quote":"In Palao, we say we are a friend to all.","topic":"Pacific security","kind":"fact"},{"t":810,"quote":"We choose our partners based on our shared values of democracy, human rights, and a rules-based international order.","topic":"Pacific security","kind":"fact"},{"t":840,"quote":"Yet the UN marginalizes Taiwan's 23 million people, disregarding that fin foundational purpose.","topic":"Taiwan UN participation","kind":"fact"},{"t":930,"quote":"political momentum is growing and resources are beginning to mobilize even amidst a complex geopolitical landscape","topic":"Climate change","kind":"fact"},{"t":968,"quote":"In Palao we also say knowledge is like ocean waves. It comes in many forms and sizes. Yet no wave overpowers another and they ultimately reach the same shore.","topic":"Multilateralism","kind":"fact"}],"promises":[],"attacks":[],"greece":[],"said":[],"pickup":[],"transcript":[{"t":2,"topic":"UNGA greetings","text":"The assembly will now hear an address by his excellency Sir Angel Whips, President of the Republic of Palao. I request protocol to escort his and I invite him to address this August assembly. Mr. President, congratulations on your election as President of the 81st session of the UN General Assembly. Terry General, excellencies, ladies and gentlemen, Ali and warm greetings from the people of Palao. Secretary General Antonio Gutierrez, thank you for your leadership and service to the United Nations."},{"t":67,"topic":"Climate change","text":"Your climate leadership, steadfast defense of multilateralism, international law, human dignity, and the voices of the vulnerable carries a special meaning for small island developing states. I stand before this assembly for a people whose future depends on a healthy ocean and a stable climate and the sovereign right to determine their own path. For us, sovereignty is lived in our ability to feed our from healthy oceans, power our homes from distant fuel markets, and protect our shorelines from rising seas, and chart our own path. It is a responsibility that grows more urgent each day, especially as UNEP's latest findings make clear that the world is now certain to exceed This reality must strengthen our resolve to deliver what we have promised, prepare our communities for the impacts science tells us are inevitable."},{"t":151,"topic":"Pacific ocean","text":"Small island states, young people, scientists, civil society, indigenous communities, and responsible partners have already raised climate am am am am am am am am am am am am am am ambition, exhilarated the shift to renewable energy and exposed the true cost of inaction. We have called for ambition that matches science, demonstrated that ocean stewardship can protect while supporting livelihoods and insisted on a voice on a stronger voice for small island states in decisions that shape our future. Pacific leaders have charted a practical roadmap through the unlocking blue Pacific prosperity UBPPP launched at COP 28 and reinforced by the Pacific leaders ocean statement adopted in Palao. UBBB unites 22 Pacific countries and territories to mobilize accessible catalytic catalytic investment for 100% sustainable ocean management robust food systems and resilience advancing our shared 30 by30 commitment."},{"t":238,"topic":"Palau ocean policy","text":"We continue to seek and expand investment to the UBBP to meet its goals and deliver lasting resilience for our communities. Palao is translating that UBPB vision into national action. We have launched our sustainable ocean policy that commits 100% effective science-based and adaptive management of our ocean, balancing protection with production to deliver the optimal benefits for our people. In line with this effort, we support with support from partners like Japan, we are working to develop fishing ports and other critical infrastructure to truly capture the value of resources harvested in our waters. [sighs] as chair of the Pacific Island Forum and AOSIS and through Palao's leadership on the high level panel for sustainable ocean economy."},{"t":302,"topic":"Climate finance","text":"We continue to call for an a ocean agenda that meets the scale of this challenge. But Mr. President, the task now is delivery. We need financing that reaches communities without adding debt. adaptation finance that is accessible to countries already bearing the cost of the problems they did not create and full support of the loss and damage and special and the special circumstances of SIDS. This means grant-based and concessional grid readiness and storage, energy use, and support that respects our circumstances while enabling delivery at scale. Those who contributed the least to this climate crisis yet confront the worst threats of rising sea levels must not be burdened with simply to purchase a life jacket for their survival."},{"t":375,"topic":"Climate finance","text":"International financial institutions must look beyond income and account for vulnerabilities of SIDS. Climate exposure, remoteness, nar narrow economies, and limited access to affordable finance must be considered. The Antigua and Barbuda agenda for SIDS provides a strong roadmap for resilience, but requires urgent, predictable, and scaled up support. The Pacific re resilience facility is one practical answer. The endorsed by the Pacific leaders. The PRF is the first Pacific leown owned and managed regional financing facility dedicated to climate and disaster resilience and the first international institution collectively owned by the Pacific focused on turning resources into real community level resilience."},{"t":439,"topic":"Nicotine addiction","text":"The PRF reflects the kind of capital the world should support. Resilience is also about safeguarding public health. And I commend Palao's first lady for advancing efforts to combat tobacco and nicotine use with a focus on our youth. Her efforts led to the formal request to the UN tech secretary general to initiate a WHO review of nicotine as a psychotropic substance. Globally, nicotine claims over se seven million lives annually and more than a billion trap in addiction. Protecting our future requires expanding prevention, enhancing cessation support, and enacting strong policies to diminish the appeal and affordability of these harmful products. No country should have to choose between health, of its children, and the commercial interest of an in industry that is built on addiction."},{"t":508,"topic":"Pacific energy","text":"We call for stronger international cooperation to protect young people from nicotine dependence and to put public health before profit. Resilience must also transform into how we tra power our homes, move our people and connect our islands. Energy security is climate security and national security. Through the call to action, the Pacific reaffirmed a shared vision of 100% renewable energy and a just, inclusive and equitable transition away from fossil fuels. This is not about reducing emissions. It is about reducing vulnerability to imported fuel, external shocks, and prices we do not control."},{"t":571,"topic":"Palau energy","text":"Palao is carrying that regional commitment into national action. Our latest commitment targets a 44% reduction in fossil fuel use by supported by renewable energy generation and practical policies that make the transition affordable and reliable. Our energy future reflects a larger truth. Resilience requires partnership shaped by our pri priorities and respects our sovereignty. How we protect our ocean, confront climate change, and power our islands leads directly to how the world engages with us. must never come before must never become pressure and assistance must never come at the cost of the nation's values, institutions or the freedom to choose."},{"t":639,"topic":"Russia Ukraine war","text":"Sovereignty is not isolation. It is the freedom to cooperate through mutual respect, transparency, accountability, dialogue, and international law. This principle matters because we have seen what can happen when tensions build, when concerns are ignored, and when channels for dialogue are left too narrow for the challenges before us. The Russia Ukraine war is a painful reminder of the tragic human toll that occurs when diplomacy gives way to conflict and how challenging it is to deescalate tensions once violence erupts. The straight of Hormuz situation demonstrates how quickly disruption in an important waterway threatens international stability, energy security and trade worldwide. Reaffirming the primary responsibility of the UN charter to maintain global peace and security."},{"t":703,"topic":"Iran","text":"We uphold the sovereignty of Ba Bahrain, Jordan, Kuwait, Oman, Qatar, Saudi Arabia, and the UAE and condemn the actions of that of Iran to jeopardize maritime security and aim to obstruct, close and inter interfere with international navigation through the strait. At our Pacific leaders meeting in Palao, leaders expressed deep concern that China's ballistic missile test overflow several Pacific nations without adequate nos notice. Let me remind you, our region must never be treated as an empty expanse for strategic competition or test of military power. The Pacific is home to peoples, communities, cultures, fisheries, and ecosystems. It is the foundation of our security and the source of our nourishment and lifeline for the global community."},{"t":768,"topic":"Pacific security","text":"In the face of these risks, the Pacific way is to address tensions before they become crisis. Make room for dialogue before disagreement becomes conflict. seek inclusion rather than isolation and uphold respect, restraint, and international law. The Pacific is our home, not a theater for geopolitical competition. It must remain an ocean of peace where nations meet in cooperation, international laws respected, and the security of the Pacific peoples is never compromised. In Palao, we say we are a friend to all. We choose our partners based on our shared values of democracy, human rights, and a rules-based international order. Principles that underpin our friendship with Taiwan, a trusted partner that can contribute even more fully if given the space to do so."},{"t":833,"topic":"Taiwan UN participation","text":"The UN charter begins with the commitment, we the peoples. Yet the UN marginalizes Taiwan's 23 million people, disregarding that fin foundational purpose. We stand with likeminded partners in calling for the reversal of misrepresent interpretations of the rules and procedures that have constrained Taiwan's meaningful participation in this body. Under the UN charter, small states are sovereign states with the right to determine their own future, choose their partners, and pursue development that serves their people. We urge all parties to preserve peace and stability, resol resolve differences peacefully and choose dialogue over Beyond politics and policy, one truth should unite us."},{"t":899,"topic":"Climate change","text":"Our children and their children deserve a world that is safe, healthy, and clean. For that reason, our discussions here and beyond must lead to action. Action that protects the conditions in which every child can live, grow, and thrive. We acknowledge while not yet at the scale required that the architecture is being built, political momentum is growing and resources are beginning to mobilize even amidst a complex geopolitical landscape. Our traditional wisdom reminds us be strong and do not give up. The shore is near. The promise of multilateralism is that even the smallest can be heard and that the many voices shaped by different histories and experiences can move toward a common shore."},{"t":968,"topic":"Multilateralism","text":"In Palao we also say knowledge is like ocean waves. It comes in many forms and sizes. Yet no wave overpowers another and they ultimately reach the same shore. Let us leave this assembly committed to multilateralism that honors every voice, values every form of knowledge and carries us toward a safer, healthier and more peaceful world. Mulan and I thank you. On behalf of the assembly, I wish to thank the President of the Republic of"}],"compare":[{"topic":"Climate Change","share":0.3043,"mean":0.0414,"rank":3,"others":77},{"topic":"Indo-Pacific","share":0.2263,"mean":0.003,"rank":1,"others":6},{"topic":"Global Health","share":0.0729,"mean":0.0021,"rank":2,"others":6},{"topic":"Taiwan","share":0.0697,"mean":0.0025,"rank":3,"others":7},{"topic":"Iran","share":0.0684,"mean":0.0135,"rank":17,"others":25},{"topic":"Russia-Ukraine War","share":0.0675,"mean":0.0351,"rank":38,"others":44},{"topic":"International Law & Order","share":0.0522,"mean":0.0604,"rank":86,"others":102}]};
